:root {
  --bg: #f6f5fb;
  --card: #ffffff;
  --text: #17142b;
  --muted: #6b6785;
  --line: #e7e4f2;
  --soft: #efecfb;
  --brand: #5b3df5;
  --brand-2: #c03cf0;
  --accent: #ff9f1c;
  --like: #ff3d6e;
  --ok: #10b981;
  --danger: #e11d48;
  --grad: linear-gradient(135deg, #5b3df5 0%, #c03cf0 55%, #ff9f1c 100%);
  --radius: 18px;
  --shadow: 0 1px 2px rgba(23, 20, 43, .05), 0 6px 24px rgba(23, 20, 43, .06);
  --nav-h: 64px;
  --head-h: 56px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f0d19;
    --card: #1a1727;
    --text: #f1effa;
    --muted: #a19cba;
    --line: #2c2840;
    --soft: #252136;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3);
    color-scheme: dark;
  }
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
button, input, textarea, select { font: inherit; color: inherit; }
img { display: block; max-width: 100%; }
h1, h2, h3 { margin: 0; line-height: 1.2; }

/* ---------- Estrutura ---------- */
.app { max-width: 620px; margin: 0 auto; min-height: 100dvh; padding-bottom: calc(var(--nav-h) + env(safe-area-inset-bottom) + 16px); }
.app.no-nav { padding-bottom: 24px; }
.topbar {
  position: sticky; top: 0; z-index: 20; height: var(--head-h);
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 0 16px; background: color-mix(in srgb, var(--bg) 85%, transparent);
  backdrop-filter: saturate(1.6) blur(14px); -webkit-backdrop-filter: saturate(1.6) blur(14px);
  border-bottom: 1px solid var(--line);
}
.logo { font-weight: 900; font-size: 26px; letter-spacing: -1px; background: var(--grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.topbar .title { font-weight: 700; font-size: 17px; flex: 1; text-align: center; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.icon-btn { background: none; border: 0; padding: 8px; border-radius: 12px; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; color: var(--text); }
.icon-btn:active { background: var(--soft); }
.icon-btn svg { width: 24px; height: 24px; }
.view { padding: 12px 12px 0; }

.bottomnav {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 30;
  height: calc(var(--nav-h) + env(safe-area-inset-bottom)); padding-bottom: env(safe-area-inset-bottom);
  background: color-mix(in srgb, var(--card) 92%, transparent);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  border-top: 1px solid var(--line);
}
.bottomnav .inner { max-width: 620px; margin: 0 auto; height: var(--nav-h); display: grid; grid-template-columns: repeat(5, 1fr); align-items: center; }
.bottomnav a { display: flex; flex-direction: column; align-items: center; gap: 2px; font-size: 11px; color: var(--muted); font-weight: 600; }
.bottomnav a svg { width: 26px; height: 26px; }
.bottomnav a.active { color: var(--brand); }
.bottomnav a.plus span.plus-btn { width: 48px; height: 38px; border-radius: 14px; background: var(--grad); color: #fff; display: grid; place-items: center; box-shadow: 0 6px 16px rgba(91, 61, 245, .35); }
.bottomnav a.plus svg { width: 24px; height: 24px; }

/* ---------- Componentes ---------- */
.card { background: var(--card); border-radius: var(--radius); box-shadow: var(--shadow); border: 1px solid var(--line); }
.pad { padding: 16px; }
.stack > * + * { margin-top: 12px; }
.row { display: flex; align-items: center; gap: 10px; }
.between { justify-content: space-between; }
.grow { flex: 1; min-width: 0; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
.tiny { font-size: 12px; }
.bold { font-weight: 700; }
.center { text-align: center; }
.ellipsis { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.section-title { font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin: 20px 4px 8px; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  border: 0; border-radius: 14px; padding: 12px 18px; font-weight: 700; cursor: pointer;
  background: var(--soft); color: var(--text); min-height: 46px; transition: transform .08s ease, opacity .2s;
}
.btn:active { transform: scale(.98); }
.btn[disabled] { opacity: .55; pointer-events: none; }
.btn.primary { background: var(--grad); color: #fff; box-shadow: 0 6px 18px rgba(91, 61, 245, .28); }
.btn.outline { background: transparent; border: 1.5px solid var(--line); }
.btn.danger { background: color-mix(in srgb, var(--danger) 12%, transparent); color: var(--danger); }
.btn.block { width: 100%; }
.btn.sm { min-height: 36px; padding: 7px 14px; font-size: 14px; border-radius: 12px; }

.field { display: block; }
.field > span { display: block; font-size: 13px; font-weight: 700; margin: 0 2px 6px; color: var(--muted); }
.input, textarea.input, select.input {
  width: 100%; border: 1.5px solid var(--line); background: var(--card); border-radius: 14px;
  padding: 12px 14px; min-height: 46px; outline: none; transition: border-color .15s;
}
textarea.input { resize: vertical; min-height: 90px; }
.input:focus { border-color: var(--brand); }
.hint { font-size: 12px; color: var(--muted); margin: 6px 2px 0; }

.segmented { display: flex; background: var(--soft); padding: 4px; border-radius: 14px; gap: 4px; }
.segmented button { flex: 1; border: 0; background: transparent; border-radius: 10px; padding: 9px 8px; font-weight: 700; font-size: 14px; color: var(--muted); cursor: pointer; }
.segmented button.on { background: var(--card); color: var(--text); box-shadow: var(--shadow); }

.chips { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; scrollbar-width: none; }
.chip { border: 1.5px solid var(--line); background: var(--card); border-radius: 999px; padding: 6px 14px; font-weight: 700; font-size: 13px; cursor: pointer; white-space: nowrap; }
.chip.on { background: var(--text); color: var(--bg); border-color: var(--text); }

.badge { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 800; padding: 2px 8px; border-radius: 999px; background: var(--soft); color: var(--muted); vertical-align: middle; }
.badge.banca { background: color-mix(in srgb, var(--accent) 18%, transparent); color: #b45309; }
.badge.prof { background: color-mix(in srgb, var(--brand) 14%, transparent); color: var(--brand); }
.badge.admin { background: var(--grad); color: #fff; }
@media (prefers-color-scheme: dark) { .badge.banca { color: #fbbf24; } .badge.prof { color: #a594ff; } }

.avatar { flex: none; border-radius: 50%; display: grid; place-items: center; color: #fff; font-weight: 800; overflow: hidden; background: var(--grad); }
.avatar img { width: 100%; height: 100%; object-fit: cover; }
.avatar.ring { padding: 3px; background: var(--grad); }
.avatar.ring > * { border-radius: 50%; border: 3px solid var(--card); width: 100%; height: 100%; display: grid; place-items: center; overflow: hidden; }

.empty { text-align: center; padding: 40px 20px; color: var(--muted); }
.empty .big { font-size: 48px; margin-bottom: 8px; }

.toast {
  position: fixed; left: 50%; bottom: calc(var(--nav-h) + 24px + env(safe-area-inset-bottom)); transform: translateX(-50%) translateY(20px);
  background: var(--text); color: var(--bg); padding: 12px 18px; border-radius: 14px; font-weight: 700; z-index: 100;
  opacity: 0; transition: all .25s ease; max-width: calc(100% - 32px); box-shadow: 0 10px 30px rgba(0,0,0,.25); text-align: center;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.spinner { width: 28px; height: 28px; border-radius: 50%; border: 3px solid var(--soft); border-top-color: var(--brand); animation: spin .8s linear infinite; margin: 40px auto; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- Celebração (troféu desbloqueado) ---------- */
.celebrate { position: fixed; inset: 0; z-index: 200; display: grid; place-items: center; background: rgba(10, 8, 20, .6); backdrop-filter: blur(4px); padding: 24px; animation: fade .2s ease; }
.celebrate .box { background: var(--card); border-radius: 26px; padding: 28px 24px; text-align: center; max-width: 340px; width: 100%; animation: pop .35s cubic-bezier(.2, 1.4, .4, 1); }
.celebrate .emoji { font-size: 72px; line-height: 1; margin-bottom: 8px; }
@keyframes pop { from { transform: scale(.7); opacity: 0; } to { transform: scale(1); opacity: 1; } }
@keyframes fade { from { opacity: 0; } }

/* ---------- Login ---------- */
.auth-hero { text-align: center; padding: 36px 16px 20px; }
.auth-hero .logo { font-size: 56px; letter-spacing: -2px; }
.auth-hero p { margin: 6px 0 0; color: var(--muted); }
.divider { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 13px; margin: 18px 0; }
.divider::before, .divider::after { content: ""; flex: 1; height: 1px; background: var(--line); }
.banca-card { background: var(--grad); color: #fff; border: 0; }
.banca-card .btn { background: #fff; color: var(--brand); }

/* ---------- Feed ---------- */
.post { margin-bottom: 14px; overflow: hidden; }
.post-head { padding: 12px 14px; }
.post-head .name { font-weight: 700; }
.post-media { position: relative; background: var(--soft); aspect-ratio: 1 / 1; user-select: none; }
.post-media img { width: 100%; height: 100%; object-fit: cover; }
.post-media .heart-pop { position: absolute; inset: 0; display: grid; place-items: center; font-size: 96px; pointer-events: none; opacity: 0; transform: scale(.4); }
.post-media .heart-pop.go { animation: heart .8s ease; }
@keyframes heart { 30% { opacity: 1; transform: scale(1.1); } 60% { opacity: 1; transform: scale(1); } 100% { opacity: 0; transform: scale(1); } }
.post-actions { padding: 8px 8px 0; display: flex; align-items: center; gap: 2px; }
.post-actions button { background: none; border: 0; display: inline-flex; align-items: center; gap: 6px; padding: 8px; border-radius: 12px; cursor: pointer; font-weight: 700; }
.post-actions svg { width: 26px; height: 26px; }
.post-actions .liked { color: var(--like); }
.post-actions .liked svg { fill: var(--like); animation: pop .3s ease; }
.post-body { padding: 4px 16px 14px; }
.post-body .caption { white-space: pre-wrap; overflow-wrap: anywhere; }

.achv { padding: 26px 20px; color: #fff; text-align: center; position: relative; overflow: hidden; }
.achv::before, .achv::after { content: ""; position: absolute; border-radius: 50%; background: rgba(255,255,255,.12); }
.achv::before { width: 220px; height: 220px; right: -60px; top: -80px; }
.achv::after { width: 160px; height: 160px; left: -50px; bottom: -70px; }
.achv .emoji { font-size: 64px; line-height: 1.1; position: relative; filter: drop-shadow(0 6px 10px rgba(0,0,0,.2)); }
.achv .kicker { text-transform: uppercase; font-size: 12px; font-weight: 800; letter-spacing: .1em; opacity: .9; margin-top: 8px; position: relative; }
.achv .what { font-size: 22px; font-weight: 900; position: relative; margin-top: 2px; }
.achv .why { position: relative; margin: 10px auto 0; max-width: 420px; font-style: italic; opacity: .95; }
.achv .pts { position: relative; display: inline-block; margin-top: 12px; background: rgba(255,255,255,.22); border-radius: 999px; padding: 4px 12px; font-weight: 800; font-size: 13px; }
.tier-bronze { background: linear-gradient(135deg, #b45309, #f59e0b); }
.tier-prata { background: linear-gradient(135deg, #475569, #94a3b8); }
.tier-ouro { background: linear-gradient(135deg, #ca8a04, #facc15 60%, #f97316); }

.comment { display: flex; gap: 10px; padding: 10px 0; }
.comment .bubble { background: var(--soft); border-radius: 4px 16px 16px 16px; padding: 8px 12px; overflow-wrap: anywhere; }
.comment-form { position: sticky; bottom: calc(var(--nav-h) + env(safe-area-inset-bottom)); background: var(--bg); padding: 10px 0; display: flex; gap: 8px; }

/* ---------- Perfil ---------- */
.profile-head { text-align: center; padding: 22px 16px 16px; }
.profile-head h2 { margin-top: 10px; font-size: 22px; }
.profile-head .bio { margin: 8px auto 0; max-width: 420px; white-space: pre-wrap; overflow-wrap: anywhere; }
.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 16px; }
.stat { background: var(--soft); border-radius: 14px; padding: 10px 6px; text-align: center; }
.stat b { display: block; font-size: 20px; }
.stat span { font-size: 12px; color: var(--muted); font-weight: 600; }
.stat.hl { background: var(--grad); color: #fff; }
.stat.hl span { color: rgba(255,255,255,.85); }
.trophy-strip { display: flex; gap: 10px; overflow-x: auto; padding: 2px 2px 6px; scrollbar-width: none; }
.trophy-pill { flex: none; width: 78px; text-align: center; }
.trophy-pill .ic { width: 62px; height: 62px; border-radius: 50%; margin: 0 auto; display: grid; place-items: center; font-size: 30px; color: #fff; position: relative; }
.trophy-pill .ic .count { position: absolute; right: -2px; bottom: -2px; background: var(--text); color: var(--bg); font-size: 11px; font-weight: 800; border-radius: 999px; padding: 1px 6px; }
.trophy-pill .nm { font-size: 11px; font-weight: 700; margin-top: 4px; line-height: 1.2; }
.grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; border-radius: 14px; overflow: hidden; }
.grid3 a { aspect-ratio: 1; background: var(--soft); }
.grid3 img { width: 100%; height: 100%; object-fit: cover; }

/* ---------- Conquistas ---------- */
.achv-summary { padding: 18px; color: #fff; background: var(--grad); border: 0; }
.achv-summary .big { font-size: 34px; font-weight: 900; line-height: 1; }
.trophy-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
@media (min-width: 520px) { .trophy-grid { grid-template-columns: repeat(3, 1fr); } }
.trophy { padding: 14px 12px; text-align: center; position: relative; }
.trophy .ic { width: 66px; height: 66px; margin: 0 auto 8px; border-radius: 50%; display: grid; place-items: center; font-size: 34px; }
.trophy.locked .ic { background: var(--soft) !important; filter: grayscale(1); opacity: .55; }
.trophy .lock { position: absolute; top: 10px; right: 10px; font-size: 14px; opacity: .6; }
.trophy h3 { font-size: 14px; }
.trophy p { margin: 4px 0 8px; font-size: 12px; color: var(--muted); min-height: 32px; }
.bar { height: 8px; background: var(--soft); border-radius: 999px; overflow: hidden; }
.bar > i { display: block; height: 100%; background: var(--grad); border-radius: inherit; }
.trophy .meta { display: flex; justify-content: space-between; font-size: 11px; font-weight: 700; color: var(--muted); margin-top: 6px; }
.trophy.done .meta .ok { color: var(--ok); }
.medal-type { padding: 12px 14px; }
.medal-type .ic { width: 52px; height: 52px; border-radius: 50%; display: grid; place-items: center; font-size: 26px; flex: none; }
.medal-type.locked .ic { filter: grayscale(1); opacity: .45; background: var(--soft) !important; }

