.podium .p1 .block { height: 96px; background: linear-gradient(180deg, #facc15, #f59e0b); }
.podium .p2 .block { height: 72px; background: linear-gradient(180deg, #cbd5e1, #94a3b8); }
.podium .p3 .block { height: 56px; background: linear-gradient(180deg, #fdba74, #c2410c); }
.podium .nm { font-weight: 800; font-size: 13px; margin-top: 6px; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.podium .pt { font-size: 12px; color: var(--muted); font-weight: 700; }
.rank-row { display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-bottom: 1px solid var(--line); }
