.rank-row .pos { width: 28px; text-align: center; font-weight: 900; color: var(--muted); }
.rank-row.me { background: color-mix(in srgb, var(--brand) 9%, transparent); }
.rank-row .pts { font-weight: 900; }
.me-bar { position: sticky; bottom: calc(var(--nav-h) + env(safe-area-inset-bottom) + 8px); margin-top: 12px; background: var(--text); color: var(--bg); border: 0; }
.me-bar .muted { color: color-mix(in srgb, var(--bg) 70%, transparent); }

/* ---------- Avisos ---------- */
.notice { padding: 16px; margin-bottom: 12px; }
.notice.pinned { border: 2px solid transparent; background: linear-gradient(var(--card), var(--card)) padding-box, var(--grad) border-box; }
.notice h3 { font-size: 17px; margin: 10px 0 6px; }
.notice .body { white-space: pre-wrap; overflow-wrap: anywhere; }

/* ---------- Publicar ---------- */
.picker { aspect-ratio: 1; border: 2px dashed var(--line); border-radius: var(--radius); display: grid; place-items: center; text-align: center; cursor: pointer; background: var(--card); overflow: hidden; position: relative; }
.picker img { width: 100%; height: 100%; object-fit: cover; position: absolute; inset: 0; }
.picker .ph { color: var(--muted); padding: 20px; }
.picker .ph .big { font-size: 48px; }
.medal-pick { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.medal-pick button { border: 2px solid var(--line); background: var(--card); border-radius: 16px; padding: 12px 8px; cursor: pointer; text-align: center; }
.medal-pick button .e { font-size: 30px; }
.medal-pick button.on { border-color: var(--brand); background: color-mix(in srgb, var(--brand) 8%, var(--card)); }
.person-pick { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 14px; cursor: pointer; border: 2px solid transparent; }
.person-pick:hover { background: var(--soft); }
.person-pick.on { border-color: var(--brand); background: color-mix(in srgb, var(--brand) 8%, var(--card)); }

