  --muted: #6b6785;
  --line: #e7e4f2;
  --soft: #efecfb;
  --brand: #5b3df5;
  --brand-2: #c03cf0;
  --accent: #ff9f1c;
  --like: #ff3d6e;
  --ok: #10b981;
  --danger: #e11d48;
  --grad: linear-gradient(135deg, #5b3df5 0%, #c03cf0 55%, #ff9f1c 100%);
  --radius: 18px;
  --shadow: 0 1px 2px rgba(23, 20, 43, .05), 0 6px 24px rgba(23, 20, 43, .06);
  --nav-h: 64px;
  --head-h: 56px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f0d19;
    --card: #1a1727;
    --text: #f1effa;
    --muted: #a19cba;
    --line: #2c2840;
    --soft: #252136;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3);
    color-scheme: dark;
  }
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
button, input, textarea, select { font: inherit; color: inherit; }
img { display: block; max-width: 100%; }
h1, h2, h3 { margin: 0; line-height: 1.2; }

/* ---------- Estrutura ---------- */
.app { max-width: 620px; margin: 0 auto; min-height: 100dvh; padding-bottom: calc(var(--nav-h) + env(safe-area-inset-bottom) + 16px); }
