:root {
  --bg: #f6f5fb;
  --card: #ffffff;
  --text: #17142b;
  --muted: #6b6785;
  --line: #e7e4f2;
  --soft: #efecfb;
  --brand: #5b3df5;
  --brand-2: #c03cf0;
  --accent: #ff9f1c;
  --like: #ff3d6e;
  --ok: #10b981;
  --danger: #e11d48;
  --grad: linear-gradient(135deg, #5b3df5 0%, #c03cf0 55%, #ff9f1c 100%);
  --radius: 18px;
  --shadow: 0 1px 2px rgba(23, 20, 43, .05), 0 6px 24px rgba(23, 20, 43, .06);
  --nav-h: 64px;
  --head-h: 56px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f0d19;
    --card: #1a1727;
    --text: #f1effa;
    --muted: #a19cba;
    --line: #2c2840;
    --soft: #252136;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3);
    color-scheme: dark;
  }
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
button, input, textarea, select { font: inherit; color: inherit; }
img { display: block; max-width: 100%; }
h1, h2, h3 { margin: 0; line-height: 1.2; }

/* ---------- Estrutura ---------- */
.app { max-width: 620px; margin: 0 auto; min-height: 100dvh; padding-bottom: calc(var(--nav-h) + env(safe-area-inset-bottom) + 16px); }
.app.no-nav { padding-bottom: 24px; }
.topbar {
  position: sticky; top: 0; z-index: 20; height: var(--head-h);
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 0 16px; background: color-mix(in srgb, var(--bg) 85%, transparent);
  backdrop-filter: saturate(1.6) blur(14px); -webkit-backdrop-filter: saturate(1.6) blur(14px);
  border-bottom: 1px solid var(--line);
}
.logo { font-weight: 900; font-size: 26px; letter-spacing: -1px; background: var(--grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.topbar .title { font-weight: 700; font-size: 17px; flex: 1; text-align: center; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.icon-btn { background: none; border: 0; padding: 8px; border-radius: 12px; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; color: var(--text); }
.icon-btn:active { background: var(--soft); }
.icon-btn svg { width: 24px; height: 24px; }
.view { padding: 12px 12px 0; }

.bottomnav {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 30;
  height: calc(var(--nav-h) + env(safe-area-inset-bottom)); padding-bottom: env(safe-area-inset-bottom);
  background: color-mix(in srgb, var(--card) 92%, transparent);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  border-top: 1px solid var(--line);
}
.bottomnav .inner { max-width: 620px; margin: 0 auto; height: var(--nav-h); display: grid; grid-template-columns: repeat(5, 1fr); align-items: center; }
.bottomnav a { display: flex; flex-direction: column; align-items: center; gap: 2px; font-size: 11px; color: var(--muted); font-weight: 600; }
.bottomnav a svg { width: 26px; height: 26px; }
.bottomnav a.active { color: var(--brand); }
.bottomnav a.plus span.plus-btn { width: 48px; height: 38px; border-radius: 14px; background: var(--grad); color: #fff; display: grid; place-items: center; box-shadow: 0 6px 16px rgba(91, 61, 245, .35); }
.bottomnav a.plus svg { width: 24px; height: 24px; }

/* ---------- Componentes ---------- */
.card { background: var(--card); border-radius: var(--radius); box-shadow: var(--shadow); border: 1px solid var(--line); }
.pad { padding: 16px; }
.stack > * + * { margin-top: 12px; }
.row { display: flex; align-items: center; gap: 10px; }
.between { justify-content: space-between; }
.grow { flex: 1; min-width: 0; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
.tiny { font-size: 12px; }
.bold { font-weight: 700; }
.center { text-align: center; }
.ellipsis { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.section-title { font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin: 20px 4px 8px; }

