.avatar { flex: none; border-radius: 50%; display: grid; place-items: center; color: #fff; font-weight: 800; overflow: hidden; background: var(--grad); }
.avatar img { width: 100%; height: 100%; object-fit: cover; }
.avatar.ring { padding: 3px; background: var(--grad); }
.avatar.ring > * { border-radius: 50%; border: 3px solid var(--card); width: 100%; height: 100%; display: grid; place-items: center; overflow: hidden; }

.empty { text-align: center; padding: 40px 20px; color: var(--muted); }
.empty .big { font-size: 48px; margin-bottom: 8px; }

.toast {
  position: fixed; left: 50%; bottom: calc(var(--nav-h) + 24px + env(safe-area-inset-bottom)); transform: translateX(-50%) translateY(20px);
  background: var(--text); color: var(--bg); padding: 12px 18px; border-radius: 14px; font-weight: 700; z-index: 100;
  opacity: 0; transition: all .25s ease; max-width: calc(100% - 32px); box-shadow: 0 10px 30px rgba(0,0,0,.25); text-align: center;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.spinner { width: 28px; height: 28px; border-radius: 50%; border: 3px solid var(--soft); border-top-color: var(--brand); animation: spin .8s linear infinite; margin: 40px auto; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- Celebração (troféu desbloqueado) ---------- */
