.trophy-pill .nm { font-size: 11px; font-weight: 700; margin-top: 4px; line-height: 1.2; }
.grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; border-radius: 14px; overflow: hidden; }
.grid3 a { aspect-ratio: 1; background: var(--soft); }
.grid3 img { width: 100%; height: 100%; object-fit: cover; }

/* ---------- Conquistas ---------- */
.achv-summary { padding: 18px; color: #fff; background: var(--grad); border: 0; }
.achv-summary .big { font-size: 34px; font-weight: 900; line-height: 1; }
.trophy-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
@media (min-width: 520px) { .trophy-grid { grid-template-columns: repeat(3, 1fr); } }
.trophy { padding: 14px 12px; text-align: center; position: relative; }
.trophy .ic { width: 66px; height: 66px; margin: 0 auto 8px; border-radius: 50%; display: grid; place-items: center; font-size: 34px; }
.trophy.locked .ic { background: var(--soft) !important; filter: grayscale(1); opacity: .55; }
.trophy .lock { position: absolute; top: 10px; right: 10px; font-size: 14px; opacity: .6; }
.trophy h3 { font-size: 14px; }
.trophy p { margin: 4px 0 8px; font-size: 12px; color: var(--muted); min-height: 32px; }
.bar { height: 8px; background: var(--soft); border-radius: 999px; overflow: hidden; }
.bar > i { display: block; height: 100%; background: var(--grad); border-radius: inherit; }
.trophy .meta { display: flex; justify-content: space-between; font-size: 11px; font-weight: 700; color: var(--muted); margin-top: 6px; }
.trophy.done .meta .ok { color: var(--ok); }
.medal-type { padding: 12px 14px; }
.medal-type .ic { width: 52px; height: 52px; border-radius: 50%; display: grid; place-items: center; font-size: 26px; flex: none; }
.medal-type.locked .ic { filter: grayscale(1); opacity: .45; background: var(--soft) !important; }

/* ---------- Ranking ---------- */
.podium { display: grid; grid-template-columns: 1fr 1.15fr 1fr; align-items: end; gap: 8px; margin: 10px 0 14px; }
.podium .spot { text-align: center; }
.podium .block { margin-top: 8px; border-radius: 14px 14px 6px 6px; color: #fff; font-weight: 900; display: grid; place-items: center; font-size: 22px; }
.podium .p1 .block { height: 96px; background: linear-gradient(180deg, #facc15, #f59e0b); }
.podium .p2 .block { height: 72px; background: linear-gradient(180deg, #cbd5e1, #94a3b8); }
.podium .p3 .block { height: 56px; background: linear-gradient(180deg, #fdba74, #c2410c); }
.podium .nm { font-weight: 800; font-size: 13px; margin-top: 6px; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.podium .pt { font-size: 12px; color: var(--muted); font-weight: 700; }
.rank-row { display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-bottom: 1px solid var(--line); }
.rank-row:last-child { border-bottom: 0; }
.rank-row .pos { width: 28px; text-align: center; font-weight: 900; color: var(--muted); }
.rank-row.me { background: color-mix(in srgb, var(--brand) 9%, transparent); }
.rank-row .pts { font-weight: 900; }
.me-bar { position: sticky; bottom: calc(var(--nav-h) + env(safe-area-inset-bottom) + 8px); margin-top: 12px; background: var(--text); color: var(--bg); border: 0; }
.me-bar .muted { color: color-mix(in srgb, var(--bg) 70%, transparent); }

/* ---------- Avisos ---------- */
.notice { padding: 16px; margin-bottom: 12px; }
.notice.pinned { border: 2px solid transparent; background: linear-gradient(var(--card), var(--card)) padding-box, var(--grad) border-box; }
.notice h3 { font-size: 17px; margin: 10px 0 6px; }
.notice .body { white-space: pre-wrap; overflow-wrap: anywhere; }

/* ---------- Publicar ---------- */
.picker { aspect-ratio: 1; border: 2px dashed var(--line); border-radius: var(--radius); display: grid; place-items: center; text-align: center; cursor: pointer; background: var(--card); overflow: hidden; position: relative; }
.picker img { width: 100%; height: 100%; object-fit: cover; position: absolute; inset: 0; }
.picker .ph { color: var(--muted); padding: 20px; }
.picker .ph .big { font-size: 48px; }
.medal-pick { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.medal-pick button { border: 2px solid var(--line); background: var(--card); border-radius: 16px; padding: 12px 8px; cursor: pointer; text-align: center; }
.medal-pick button .e { font-size: 30px; }
.medal-pick button.on { border-color: var(--brand); background: color-mix(in srgb, var(--brand) 8%, var(--card)); }
.person-pick { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 14px; cursor: pointer; border: 2px solid transparent; }
.person-pick:hover { background: var(--soft); }
.person-pick.on { border-color: var(--brand); background: color-mix(in srgb, var(--brand) 8%, var(--card)); }

