function courseOptions(selected, { placeholder = 'Escolha o curso' } = {}) {
  return `<option value="">${placeholder}</option>` + state.config.courses
    .map((c) => `<option value="${c.id}" ${Number(selected) === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('');
}
const semesterOptions = (sel) => Array.from({ length: 12 }, (_, i) => `<option value="${i + 1}" ${Number(sel) === i + 1 ? 'selected' : ''}>${i + 1}º semestre</option>`).join('');

function roleToggle(name, value) {
  return `<div class="segmented" data-role-toggle>
    <button type="button" data-v="aluno" class="${value === 'aluno' ? 'on' : ''}">🎒 Aluno</button>
    <button type="button" data-v="professor" class="${value === 'professor' ? 'on' : ''}">👩‍🏫 Professor</button>
  </div><input type="hidden" name="${name}" value="${value}">`;
}
function bindRoleToggle(form, onChange) {
  const box = $('[data-role-toggle]', form);
  box.addEventListener('click', (e) => {
    const b = e.target.closest('button');
    if (!b) return;
    $$('button', box).forEach((x) => x.classList.toggle('on', x === b));
    form.querySelector('input[name=role]').value = b.dataset.v;
    onChange(b.dataset.v);
  });
}

