// ---------------------------------------------------------------- tela: ranking
async function rankingScreen() {
  const me = state.me;
  const r = state.rank;
  if (r.scope === 'curso' && !r.course) r.course = me.course_id || state.config.courses[0]?.id;
  const view = layout({ title: 'Ranking', tab: 'ranking' }, `
    <div class="segmented" id="scope">
      <button data-v="geral" class="${r.scope === 'geral' ? 'on' : ''}">🌎 Geral</button>
      <button data-v="curso" class="${r.scope === 'curso' ? 'on' : ''}">🎓 Por curso</button>
    </div>
    ${r.scope === 'curso' ? `<div class="chips" style="margin-top:10px" id="courses">${state.config.courses.map((c) => `<button class="chip ${c.id === Number(r.course) ? 'on' : ''}" data-c="${c.id}">${esc(c.short)}</button>`).join('')}</div>` : ''}
    <div class="row" style="justify-content:center;margin-top:10px">
      <div class="segmented" id="period" style="width:240px">
        <button data-v="all" class="${r.period === 'all' ? 'on' : ''}">Sempre</button>
        <button data-v="month" class="${r.period === 'month' ? 'on' : ''}">Este mês</button>
      </div>
    </div>
    <div id="rk"><div class="spinner"></div></div>`);
  $('#scope', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { r.scope = b.dataset.v; rankingScreen(); } });
  $('#period', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { r.period = b.dataset.v; rankingScreen(); } });
  $('#courses', view)?.addEventListener('click', (e) => { const b = e.target.closest('[data-c]'); if (b) { r.course = Number(b.dataset.c); rankingScreen(); } });
  // Rola o curso escolhido para dentro da tela.
  $('#courses .chip.on', view)?.scrollIntoView({ inline: 'center', block: 'nearest' });

  const qs = new URLSearchParams({ period: r.period });
  if (r.scope === 'curso') qs.set('course', r.course);
  try {
    const { ranking } = await api(`/api/ranking?${qs}`);
    const box = $('#rk', view);
    if (!ranking.length) { box.innerHTML = '<div class="empty"><div class="big">🏁</div>Ninguém nesse ranking ainda.</div>'; return; }
    const top = ranking.slice(0, 3);
    const spot = (u, cls, pos) => u ? `<a class="spot ${cls}" href="#/perfil/${u.id}">
        <div style="display:flex;justify-content:center">${avatar(u.id, u.name, u.avatar_id, pos === 1 ? 70 : 56)}</div>
        <div class="nm">${esc(u.name)}</div><div class="pt">${fmt(u.points)} pts</div>
        <div class="block">${pos === 1 ? '🥇' : pos === 2 ? '🥈' : '🥉'}</div></a>` : '<div></div>';
    const rows = ranking.slice(3).map((u, i) => `
      <a class="rank-row ${u.id === me.id ? 'me' : ''}" href="#/perfil/${u.id}">
        <span class="pos">${i + 4}</span>${avatar(u.id, u.name, u.avatar_id, 38)}
        <div class="grow"><div class="bold ellipsis">${esc(u.name)} ${u.is_guest ? roleBadge('aluno', true) : ''}</div><div class="tiny muted">${esc(u.course || '')}</div></div>
        <span class="pts">${fmt(u.points)}</span></a>`).join('');
    const myPos = ranking.findIndex((u) => u.id === me.id);
    box.innerHTML = `
      <div class="podium">${spot(top[1], 'p2', 2)}${spot(top[0], 'p1', 1)}${spot(top[2], 'p3', 3)}</div>
      ${rows ? `<div class="card" style="overflow:hidden">${rows}</div>` : ''}
      ${myPos >= 0 ? `<div class="card pad me-bar row">
        <b style="font-size:20px">#${myPos + 1}</b>
        <div class="grow"><b>Você</b><div class="tiny muted">de ${ranking.length} ${r.scope === 'curso' ? 'no curso' : 'na UniMax'}</div></div>
        <b>${fmt(ranking[myPos].points)} pts</b></div>` : ''}`;
  } catch (err) { $('#rk', view).innerHTML = `<div class="empty">${esc(err.message)}</div>`; }
}

// ---------------------------------------------------------------- tela: conquistas
function trophyCard(t) {
  const pct = Math.round((t.progress / t.target) * 100);
  return `<div class="card trophy ${t.unlocked ? 'done' : 'locked'}">
    ${t.unlocked ? '' : '<span class="lock">🔒</span>'}
    <div class="ic tier-${t.tier}">${t.emoji}</div>
    <h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p>
    <div class="bar"><i style="width:${t.unlocked ? 100 : pct}%"></i></div>
    <div class="meta"><span>${t.unlocked ? `<span class="ok">✓ ${new Date(t.unlocked_at).toLocaleDateString('pt-BR')}</span>` : `${t.progress}/${t.target}`}</span><span>+${t.points} pts</span></div>
  </div>`;
}

async function achievementsScreen([id]) {
  const me = state.me;
  if (!id && isStaff()) return staffAchievements();
  const userId = Number(id || me.id);
  const own = userId === me.id;
  const view = layout({ title: own ? 'Minhas conquistas' : 'Conquistas', back: !own || Boolean(id), tab: 'conquistas' });
  let d;
  try { d = await api(`/api/achievements/${userId}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const got = d.trophies.filter((t) => t.unlocked).length;
  const medalCount = d.medals.length;
  const typesGot = d.medalTypes.filter((m) => m.count).length;
  const canRevoke = (m) => me.role === 'admin' || m.prof_id === me.id;
  const tabs = {
    trofeus: () => {
      const sorted = [...d.trophies].sort((a, b) => (b.unlocked - a.unlocked) || (b.progress / b.target - a.progress / a.target));
      return `<div class="trophy-grid">${sorted.map(trophyCard).join('')}</div>`;
    },
    medalhas: () => `
      <div class="card" style="overflow:hidden">${d.medalTypes.map((m) => `
        <div class="medal-type row ${m.count ? '' : 'locked'}" style="border-bottom:1px solid var(--line)">
          <div class="ic" style="background:${m.color}22">${m.emoji}</div>
          <div class="grow"><b>${esc(m.name)}</b> <span class="tiny muted">+${m.points} pts</span><div class="tiny muted">${esc(m.desc)}</div></div>
          ${m.count ? `<span class="badge" style="background:${m.color};color:#fff;font-size:13px">×${m.count}</span>` : '<span class="tiny muted bold">Falta</span>'}
        </div>`).join('')}</div>
      <div class="section-title">Histórico</div>
      ${d.medals.length ? d.medals.map((m) => `
        <div class="card pad row" style="margin-bottom:8px;align-items:flex-start">
          <div style="font-size:30px">${m.medal?.emoji || '🎖️'}</div>
          <div class="grow"><b>${esc(m.medal?.name || m.type)}</b>
            <div class="small">“${esc(m.reason)}”</div>
            <div class="tiny muted">por ${m.prof_id ? `<a href="#/perfil/${m.prof_id}" class="bold">${esc(m.prof_name)}</a>` : 'professor'} · ${timeAgo(m.created_at)}</div></div>
          ${canRevoke(m) ? `<button class="btn danger sm" data-revoke="${m.id}">Retirar</button>` : ''}
        </div>`).join('') : `<div class="empty"><div class="big">🎖️</div>${own ? 'Você ainda não recebeu medalhas. Elas são dadas pelos professores!' : 'Nenhuma medalha ainda.'}</div>`}`,
    pontos: () => `
      <div class="card pad stack">${d.pointRules.map((r) => `<div class="row"><span style="font-size:24px">${r.emoji}</span><span>${esc(r.text)}</span></div>`).join('')}</div>
      <p class="hint center" style="margin-top:12px">Os pontos somam no ranking geral e no ranking do seu curso. Apagar uma foto tira os pontos dela.</p>`,
  };
  const render = () => {
    view.innerHTML = `
      <div class="card achv-summary">
        <div class="row between">
          <div><div class="small" style="opacity:.85">${own ? 'Seus pontos' : `Pontos de ${esc(d.user.name.split(' ')[0])}`}</div><div class="big">${fmt(d.points)}</div></div>
          <div style="text-align:right" class="small"><b style="font-size:18px">${got}/${d.trophies.length}</b> troféus<br><b style="font-size:18px">${medalCount}</b> medalhas · ${typesGot}/${d.medalTypes.length} tipos</div>
        </div>
        <div class="bar" style="margin-top:12px;background:rgba(255,255,255,.25)"><i style="width:${Math.round((got / d.trophies.length) * 100)}%;background:#fff"></i></div>
      </div>
      <div class="segmented" id="atabs" style="margin:14px 0">
        <button data-v="trofeus" class="${state.achvTab === 'trofeus' ? 'on' : ''}">🏆 Troféus</button>
        <button data-v="medalhas" class="${state.achvTab === 'medalhas' ? 'on' : ''}">🎖️ Medalhas</button>
        <button data-v="pontos" class="${state.achvTab === 'pontos' ? 'on' : ''}">⭐ Pontos</button>
      </div>
      <div id="tabbody">${tabs[state.achvTab]()}</div>`;
    $('#atabs', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { state.achvTab = b.dataset.v; render(); } });
    $('#tabbody', view).addEventListener('click', async (e) => {
      const b = e.target.closest('[data-revoke]');
      if (!b || !confirm('Retirar esta medalha? Os pontos dela saem do ranking.')) return;
      try { await api(`/api/medals/${b.dataset.revoke}`, { method: 'DELETE' }); toast('Medalha retirada.'); achievementsScreen([String(userId)]); } catch (err) { toast(err.message); }
    });
  };
  render();
}

async function staffAchievements() {
  const view = layout({ title: 'Medalhas', tab: 'conquistas' });
  let given = [];
  try { given = (await api('/api/medals/given')).medals; } catch (err) { toast(err.message); }
  view.innerHTML = `
    <div class="card achv-summary">
      <div class="small" style="opacity:.85">Medalhas que você entregou</div><div class="big">${given.length}</div>
      <a href="#/medalha" class="btn" style="background:#fff;color:var(--brand);margin-top:12px">🎖️ Dar uma medalha</a>
    </div>
    <div class="section-title">Tipos de medalha</div>
    <div class="card" style="overflow:hidden">${state.config.medalTypes.map((m) => `
      <div class="medal-type row" style="border-bottom:1px solid var(--line)">
        <div class="ic" style="background:${m.color}22">${m.emoji}</div>
        <div class="grow"><b>${esc(m.name)}</b> <span class="tiny muted">+${m.points} pts</span><div class="tiny muted">${esc(m.desc)}</div></div>
      </div>`).join('')}</div>
    <div class="section-title">Entregues recentemente</div>
    <div id="given">${given.length ? given.map((m) => `
      <div class="card pad row" style="margin-bottom:8px">
        <a href="#/perfil/${m.student_id}">${avatar(m.student_id, m.student_name, m.student_avatar, 40)}</a>
        <div class="grow"><b class="ellipsis">${m.medal?.emoji || ''} ${esc(m.medal?.name || m.type)}</b> → <a href="#/perfil/${m.student_id}" class="bold">${esc(m.student_name)}</a>
          <div class="tiny muted">“${esc(m.reason)}” · ${timeAgo(m.created_at)}</div></div>
        <button class="btn danger sm" data-revoke="${m.id}">Retirar</button>
      </div>`).join('') : '<div class="empty"><div class="big">🎖️</div>Você ainda não deu nenhuma medalha.</div>'}</div>
    <div class="section-title">Como os alunos pontuam</div>
    <div class="card pad stack">${state.config.pointRules.map((r) => `<div class="row"><span style="font-size:22px">${r.emoji}</span><span class="small">${esc(r.text)}</span></div>`).join('')}</div>`;
  $('#given', view).addEventListener('click', async (e) => {
    const b = e.target.closest('[data-revoke]');
    if (!b || !confirm('Retirar esta medalha? Os pontos dela saem do ranking.')) return;
    try { await api(`/api/medals/${b.dataset.revoke}`, { method: 'DELETE' }); toast('Medalha retirada.'); staffAchievements(); } catch (err) { toast(err.message); }
  });
}

// ---------------------------------------------------------------- tela: perfil
async function profileScreen([id]) {
  const me = state.me;
  const own = Number(id) === me.id;
  const view = layout({
    title: own ? 'Meu perfil' : 'Perfil',
    back: !own,
    right: own ? `<button class="icon-btn" id="logout" aria-label="Sair">${I.logout}</button>` : ' ',
  });
  $('#logout')?.addEventListener('click', logout);
  let d;
  try { d = await api(`/api/users/${id}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const u = d.user;
  const aluno = u.role === 'aluno';
  let photos = [];
  if (aluno) {
    try { photos = (await api(`/api/feed?user=${u.id}&kind=foto&limit=60`)).posts; } catch { /* sem fotos */ }
  }
  const subtitle = aluno
    ? `${esc(u.course_name || '')}${u.semester ? ` · ${u.semester}º semestre` : ''}`
    : u.role === 'admin' ? 'Perfil oficial da UniMax' : 'Professor(a) da UniMax';
  const pos = d.positions || {};
  const stats = aluno
    ? `<div class="stats">
        <div class="stat hl"><b>${fmt(d.points)}</b><span>pontos</span></div>
        <a class="stat" href="#/ranking" data-rank="geral"><b>${pos.general ? '#' + pos.general : '–'}</b><span>no geral</span></a>
        <a class="stat" href="#/ranking" data-rank="curso"><b>${pos.course ? '#' + pos.course : '–'}</b><span>no curso</span></a>
      </div>`
    : `<div class="stats" style="grid-template-columns:1fr 1fr">
        <div class="stat hl"><b>${fmt(d.medalsGiven)}</b><span>medalhas dadas</span></div>
        <div class="stat"><b>${fmt(d.noticesCount)}</b><span>avisos</span></div>
      </div>`;
  const actions = own
    ? `<div class="row" style="margin-top:14px"><a href="#/editar" class="btn outline grow">Editar perfil</a>${aluno ? '<a href="#/conquistas" class="btn outline grow">Conquistas</a>' : ''}</div>`
    : (aluno && isStaff() ? `<a href="#/medalha?aluno=${u.id}" class="btn primary block" style="margin-top:14px">🎖️ Dar medalha</a>` : '');
  const awards = aluno ? [
    ...d.medals.map((m) => `<div class="trophy-pill"><div class="ic" style="background:${m.color}">${m.emoji}${m.count > 1 ? `<span class="count">×${m.count}</span>` : ''}</div><div class="nm">${esc(m.name)}</div></div>`),
    ...d.trophies.map((t) => `<div class="trophy-pill"><div class="ic tier-${t.tier}">${t.emoji}</div><div class="nm">${esc(t.name)}</div></div>`),
  ] : [];
  view.innerHTML = `
    <div class="card profile-head">
      <div style="display:flex;justify-content:center"><span class="avatar ring" style="width:104px;height:104px"><span>${avatar(u.id, u.name, u.avatar_id, 92)}</span></span></div>
      <h2>${esc(u.name)} ${roleBadge(u.role, u.is_guest)}</h2>
      <div class="small muted" style="margin-top:4px">${subtitle}</div>
      ${u.bio ? `<p class="bio">${esc(u.bio)}</p>` : ''}
      ${stats}${actions}
    </div>
    ${aluno ? `
      <div class="row between"><div class="section-title">Prêmios (${awards.length})</div><a href="#/conquistas/${u.id}" class="small bold" style="color:var(--brand);margin-top:12px">Ver tudo ›</a></div>
      ${awards.length ? `<div class="trophy-strip">${awards.join('')}</div>` : `<p class="muted small" style="margin:4px">${own ? 'Seus troféus e medalhas aparecem aqui. Publique sua primeira foto para começar!' : 'Nenhum prêmio ainda.'}</p>`}
      <div class="section-title">Fotos (${photos.length})</div>
      ${photos.length ? `<div class="grid3">${photos.map((p) => `<a href="#/post/${p.id}"><img src="/api/img/${p.image_id}" alt="" loading="lazy"></a>`).join('')}</div>`
        : `<div class="empty"><div class="big">📷</div>${own ? '<a href="#/novo" class="btn primary">Publicar primeira foto</a>' : 'Nenhuma foto ainda.'}</div>`}` : ''}`;
  $$('[data-rank]', view).forEach((a) => a.addEventListener('click', () => {
    state.rank.scope = a.dataset.rank;
    state.rank.course = u.course_id;
  }));
}

async function logout() {
  if (state.me?.is_guest && !confirm('Sair da conta de visitante? Para voltar, você entra pela banca de novo (com outra conta).')) return;
  await api('/api/auth/logout', { method: 'POST' }).catch(() => {});
  state.me = null;
  go('/login');
}

// ---------------------------------------------------------------- tela: editar perfil
function editProfileScreen() {
  const me = state.me;
  const aluno = me.role === 'aluno';
  const view = layout({ title: 'Editar perfil', back: true }, `
    <form id="ep" class="card pad stack">
      <label style="display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer">
        <span id="av">${avatar(me.id, me.name, me.avatar_id, 96)}</span>
        <span class="small bold" style="color:var(--brand)">Trocar foto de perfil</span>
        <input type="file" accept="image/*" hidden id="avfile">
      </label>
      <label class="field"><span>Nome</span><input class="input" name="name" value="${esc(me.name)}" maxlength="80" required></label>
      <label class="field"><span>Bio</span><textarea class="input" name="bio" maxlength="300" placeholder="Conte um pouco sobre você">${esc(me.bio)}</textarea></label>
      ${aluno ? `
        <label class="field"><span>Curso</span><select class="input" name="course_id">${courseOptions(me.course_id)}</select></label>
        <label class="field"><span>Semestre</span><select class="input" name="semester">${semesterOptions(me.semester)}</select></label>` : ''}
      ${aluno && !me.avatar_id ? '<p class="hint" style="margin:0">🪪 Dica: foto de perfil + bio desbloqueiam o troféu “Cartão de visitas”.</p>' : ''}
      <button class="btn primary block" type="submit">Salvar</button>
    </form>`);
  let avatarData = null;
  $('#avfile', view).addEventListener('change', async (e) => {
    try {
      avatarData = await resizeImage(e.target.files[0], 400, 0.85);
      $('#av', view).innerHTML = `<span class="avatar" style="width:96px;height:96px"><img src="${avatarData}" alt=""></span>`;
    } catch (err) { toast(err.message); }
  });
  onSubmit($('#ep', view), async (d) => {
    const r = await api('/api/me', { method: 'PUT', body: { ...d, avatar: avatarData || undefined } });
    await refreshMe();
    toast('Perfil atualizado!');
    go(`/perfil/${me.id}`);
    celebrate(r.trophies);
  });
}

// ---------------------------------------------------------------- roteador
const routes = [
  [/^\/?$/, feedScreen],
  [/^\/avisos$/, noticesScreen],
  [/^\/novo$/, newPostScreen],
  [/^\/medalha$/, giveMedalScreen],
  [/^\/ranking$/, rankingScreen],
  [/^\/conquistas(?:\/(\d+))?$/, achievementsScreen],
  [/^\/perfil\/(\d+)$/, profileScreen],
  [/^\/editar$/, editProfileScreen],
  [/^\/post\/(\d+)$/, postScreen],
  [/^\/login$/, loginScreen],
  [/^\/cadastro$/, registerScreen],
  [/^\/banca$/, bancaScreen],
];
const PUBLIC = ['/login', '/cadastro', '/banca'];

async function router() {
  const raw = location.hash.slice(1) || '/';
  const [path, qs] = raw.split('?');
  if (!state.me && !PUBLIC.includes(path)) return go('/login');
  if (state.me && PUBLIC.includes(path)) return go('/');
  for (const [re, screen] of routes) {
    const m = path.match(re);
    if (m) {
      window.scrollTo(0, 0);
      try {
        await screen(m.slice(1).filter((x) => x !== undefined), new URLSearchParams(qs || ''));
      } catch (err) {
        console.error(err);
        toast(err.message || 'Erro ao abrir a tela.');
      }
      return;
    }
  }
  go('/');
}

async function boot() {
  const params = new URLSearchParams(location.search);
  if (params.has('banca')) {
    state.bancaCode = params.get('banca') || '';
    history.replaceState(null, '', location.pathname + '#/banca');
  }
  try {
    const [config, me] = await Promise.all([api('/api/config'), api('/api/me')]);
    state.config = config;
    state.me = me.user;
  } catch (err) {
    root.innerHTML = `<div class="empty"><div class="big">📡</div>${esc(err.message)}<br><br><button class="btn primary" onclick="location.reload()">Tentar de novo</button></div>`;
    return;
  }
  window.addEventListener('hashchange', router);
  router();
  if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {});
}

boot();

