  try { data = await api(`/api/posts/${id}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const me = state.me;
  const p = data.post;
  const commentHtml = (c) => {
    const canDel = c.user_id === me.id || p.user_id === me.id || me.role === 'admin';
    return `<div class="comment" data-comment="${c.id}">
      <a href="#/perfil/${c.user_id}">${avatar(c.user_id, c.user_name, c.user_avatar, 34)}</a>
      <div class="grow"><div class="bubble"><a href="#/perfil/${c.user_id}" class="bold small">${esc(c.user_name)}</a> ${roleBadge(c.user_role, c.user_guest)}<div>${esc(c.body)}</div></div>
        <div class="tiny muted" style="margin:3px 6px">${timeAgo(c.created_at)}${canDel ? ` · <button class="tiny muted" style="background:none;border:0;padding:0;cursor:pointer;text-decoration:underline" data-del-comment="${c.id}">apagar</button>` : ''}</div></div></div>`;
  };
  view.innerHTML = `${postCard(p, { detail: true })}
    <div class="section-title">Comentários</div>
    <div id="comments">${data.comments.length ? data.comments.map(commentHtml).join('') : '<p class="muted small" id="no-comments" style="margin:4px">Seja o primeiro a comentar!</p>'}</div>
    <form class="comment-form" id="cform">
      <input class="input grow" name="body" placeholder="Escreva um comentário…" maxlength="500" autocomplete="off" required>
      <button class="btn primary" type="submit" aria-label="Enviar">${I.send}</button>
    </form>`;
  const form = $('#cform', view);
  onSubmit(form, async (d) => {
    await api(`/api/posts/${id}/comments`, { method: 'POST', body: d });
    postScreen([id]);
  });
  $('#comments', view).addEventListener('click', async (e) => {
    const b = e.target.closest('[data-del-comment]');
    if (!b || !confirm('Apagar este comentário?')) return;
    try {
      await api(`/api/comments/${b.dataset.delComment}`, { method: 'DELETE' });
      b.closest('.comment').remove();
    } catch (err) { toast(err.message); }
  });
}

