  $('#given', view).addEventListener('click', async (e) => {
    const b = e.target.closest('[data-revoke]');
    if (!b || !confirm('Retirar esta medalha? Os pontos dela saem do ranking.')) return;
    try { await api(`/api/medals/${b.dataset.revoke}`, { method: 'DELETE' }); toast('Medalha retirada.'); staffAchievements(); } catch (err) { toast(err.message); }
  });
}

// ---------------------------------------------------------------- tela: perfil
async function profileScreen([id]) {
  const me = state.me;
  const own = Number(id) === me.id;
  const view = layout({
    title: own ? 'Meu perfil' : 'Perfil',
    back: !own,
    right: own ? `<button class="icon-btn" id="logout" aria-label="Sair">${I.logout}</button>` : ' ',
  });
  $('#logout')?.addEventListener('click', logout);
  let d;
  try { d = await api(`/api/users/${id}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const u = d.user;
  const aluno = u.role === 'aluno';
  let photos = [];
  if (aluno) {
    try { photos = (await api(`/api/feed?user=${u.id}&kind=foto&limit=60`)).posts; } catch { /* sem fotos */ }
  }
  const subtitle = aluno
    ? `${esc(u.course_name || '')}${u.semester ? ` · ${u.semester}º semestre` : ''}`
    : u.role === 'admin' ? 'Perfil oficial da UniMax' : 'Professor(a) da UniMax';
  const pos = d.positions || {};
  const stats = aluno
    ? `<div class="stats">
        <div class="stat hl"><b>${fmt(d.points)}</b><span>pontos</span></div>
        <a class="stat" href="#/ranking" data-rank="geral"><b>${pos.general ? '#' + pos.general : '–'}</b><span>no geral</span></a>
        <a class="stat" href="#/ranking" data-rank="curso"><b>${pos.course ? '#' + pos.course : '–'}</b><span>no curso</span></a>
      </div>`
    : `<div class="stats" style="grid-template-columns:1fr 1fr">
        <div class="stat hl"><b>${fmt(d.medalsGiven)}</b><span>medalhas dadas</span></div>
        <div class="stat"><b>${fmt(d.noticesCount)}</b><span>avisos</span></div>
      </div>`;
  const actions = own
    ? `<div class="row" style="margin-top:14px"><a href="#/editar" class="btn outline grow">Editar perfil</a>${aluno ? '<a href="#/conquistas" class="btn outline grow">Conquistas</a>' : ''}</div>`
    : (aluno && isStaff() ? `<a href="#/medalha?aluno=${u.id}" class="btn primary block" style="margin-top:14px">🎖️ Dar medalha</a>` : '');
  const awards = aluno ? [
    ...d.medals.map((m) => `<div class="trophy-pill"><div class="ic" style="background:${m.color}">${m.emoji}${m.count > 1 ? `<span class="count">×${m.count}</span>` : ''}</div><div class="nm">${esc(m.name)}</div></div>`),
    ...d.trophies.map((t) => `<div class="trophy-pill"><div class="ic tier-${t.tier}">${t.emoji}</div><div class="nm">${esc(t.name)}</div></div>`),
  ] : [];
  view.innerHTML = `
    <div class="card profile-head">
      <div style="display:flex;justify-content:center"><span class="avatar ring" style="width:104px;height:104px"><span>${avatar(u.id, u.name, u.avatar_id, 92)}</span></span></div>
      <h2>${esc(u.name)} ${roleBadge(u.role, u.is_guest)}</h2>
      <div class="small muted" style="margin-top:4px">${subtitle}</div>
      ${u.bio ? `<p class="bio">${esc(u.bio)}</p>` : ''}
      ${stats}${actions}
    </div>
    ${aluno ? `
      <div class="row between"><div class="section-title">Prêmios (${awards.length})</div><a href="#/conquistas/${u.id}" class="small bold" style="color:var(--brand);margin-top:12px">Ver tudo ›</a></div>
      ${awards.length ? `<div class="trophy-strip">${awards.join('')}</div>` : `<p class="muted small" style="margin:4px">${own ? 'Seus troféus e medalhas aparecem aqui. Publique sua primeira foto para começar!' : 'Nenhum prêmio ainda.'}</p>`}
      <div class="section-title">Fotos (${photos.length})</div>
      ${photos.length ? `<div class="grid3">${photos.map((p) => `<a href="#/post/${p.id}"><img src="/api/img/${p.image_id}" alt="" loading="lazy"></a>`).join('')}</div>`
        : `<div class="empty"><div class="big">📷</div>${own ? '<a href="#/novo" class="btn primary">Publicar primeira foto</a>' : 'Nenhuma foto ainda.'}</div>`}` : ''}`;
  $$('[data-rank]', view).forEach((a) => a.addEventListener('click', () => {
    state.rank.scope = a.dataset.rank;
    state.rank.course = u.course_id;
  }));
}

async function logout() {
  if (state.me?.is_guest && !confirm('Sair da conta de visitante? Para voltar, você entra pela banca de novo (com outra conta).')) return;
  await api('/api/auth/logout', { method: 'POST' }).catch(() => {});
  state.me = null;
  go('/login');
}

// ---------------------------------------------------------------- tela: editar perfil
function editProfileScreen() {
  const me = state.me;
  const aluno = me.role === 'aluno';
  const view = layout({ title: 'Editar perfil', back: true }, `
    <form id="ep" class="card pad stack">
      <label style="display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer">
        <span id="av">${avatar(me.id, me.name, me.avatar_id, 96)}</span>
        <span class="small bold" style="color:var(--brand)">Trocar foto de perfil</span>
        <input type="file" accept="image/*" hidden id="avfile">
      </label>
      <label class="field"><span>Nome</span><input class="input" name="name" value="${esc(me.name)}" maxlength="80" required></label>
      <label class="field"><span>Bio</span><textarea class="input" name="bio" maxlength="300" placeholder="Conte um pouco sobre você">${esc(me.bio)}</textarea></label>
      ${aluno ? `
        <label class="field"><span>Curso</span><select class="input" name="course_id">${courseOptions(me.course_id)}</select></label>
        <label class="field"><span>Semestre</span><select class="input" name="semester">${semesterOptions(me.semester)}</select></label>` : ''}
      ${aluno && !me.avatar_id ? '<p class="hint" style="margin:0">🪪 Dica: foto de perfil + bio desbloqueiam o troféu “Cartão de visitas”.</p>' : ''}
      <button class="btn primary block" type="submit">Salvar</button>
    </form>`);
  let avatarData = null;
  $('#avfile', view).addEventListener('change', async (e) => {
    try {
      avatarData = await resizeImage(e.target.files[0], 400, 0.85);
      $('#av', view).innerHTML = `<span class="avatar" style="width:96px;height:96px"><img src="${avatarData}" alt=""></span>`;
    } catch (err) { toast(err.message); }
  });
  onSubmit($('#ep', view), async (d) => {
    const r = await api('/api/me', { method: 'PUT', body: { ...d, avatar: avatarData || undefined } });
    await refreshMe();
    toast('Perfil atualizado!');
    go(`/perfil/${me.id}`);
    celebrate(r.trophies);
  });
}

// ---------------------------------------------------------------- roteador
const routes = [
  [/^\/?$/, feedScreen],
  [/^\/avisos$/, noticesScreen],
  [/^\/novo$/, newPostScreen],
  [/^\/medalha$/, giveMedalScreen],
  [/^\/ranking$/, rankingScreen],
  [/^\/conquistas(?:\/(\d+))?$/, achievementsScreen],
  [/^\/perfil\/(\d+)$/, profileScreen],
  [/^\/editar$/, editProfileScreen],
  [/^\/post\/(\d+)$/, postScreen],
  [/^\/login$/, loginScreen],
  [/^\/cadastro$/, registerScreen],
  [/^\/banca$/, bancaScreen],
];
const PUBLIC = ['/login', '/cadastro', '/banca'];

async function router() {
  const raw = location.hash.slice(1) || '/';
  const [path, qs] = raw.split('?');
  if (!state.me && !PUBLIC.includes(path)) return go('/login');
  if (state.me && PUBLIC.includes(path)) return go('/');
  for (const [re, screen] of routes) {
    const m = path.match(re);
    if (m) {
      window.scrollTo(0, 0);
      try {
        await screen(m.slice(1).filter((x) => x !== undefined), new URLSearchParams(qs || ''));
      } catch (err) {
        console.error(err);
        toast(err.message || 'Erro ao abrir a tela.');
      }
      return;
    }
  }
  go('/');
}

async function boot() {
  const params = new URLSearchParams(location.search);
  if (params.has('banca')) {
    state.bancaCode = params.get('banca') || '';
    history.replaceState(null, '', location.pathname + '#/banca');
  }
  try {
    const [config, me] = await Promise.all([api('/api/config'), api('/api/me')]);
    state.config = config;
    state.me = me.user;
  } catch (err) {
    root.innerHTML = `<div class="empty"><div class="big">📡</div>${esc(err.message)}<br><br><button class="btn primary" onclick="location.reload()">Tentar de novo</button></div>`;
    return;
  }
  window.addEventListener('hashchange', router);
  router();
  if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {});
}

boot();

toolUseResult.content:
// Maxx — app do navegador (sem frameworks, sem etapa de build).
// Cada tela é uma função que monta o HTML e liga os eventos.

const state = {
  me: null,
  config: null,
  bancaCode: '',
  feedScope: 'all',
  rank: { scope: 'geral', period: 'all', course: null },
  achvTab: 'trofeus',
};
const root = document.getElementById('app');

// ---------------------------------------------------------------- utilidades
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const $ = (sel, el = root) => el.querySelector(sel);
const $$ = (sel, el = root) => [...el.querySelectorAll(sel)];
const isAluno = () => state.me?.role === 'aluno';
const isStaff = () => state.me?.role === 'professor' || state.me?.role === 'admin';
const fmt = (n) => Number(n || 0).toLocaleString('pt-BR');

function store(key, value) {
  try {
    if (value === undefined) return localStorage.getItem(key);
    localStorage.setItem(key, value);
  } catch { /* navegador sem armazenamento: tudo bem */ }
  return null;
}

async function api(path, { method = 'GET', body } = {}) {
  let res;
  try {
    res = await fetch(path, {
      method,
      headers: body ? { 'Content-Type': 'application/json' } : {},
      body: body ? JSON.stringify(body) : undefined,
      credentials: 'same-origin',
    });
  } catch {
    throw new Error('Sem conexão. Confira sua internet.');
  }
  let data = {};
  try { data = await res.json(); } catch { /* resposta sem JSON */ }
  if (res.status === 401 && !path.startsWith('/api/auth')) {
    state.me = null;
    go('/login');
  }
  if (!res.ok) throw new Error(data.error || 'Algo deu errado. Tente de novo.');
  return data;
}

function timeAgo(d) {
  const s = Math.max(0, (Date.now() - new Date(d).getTime()) / 1000);
  if (s < 60) return 'agora';
  if (s < 3600) return `há ${Math.floor(s / 60)} min`;
  if (s < 86400) return `há ${Math.floor(s / 3600)} h`;
  if (s < 86400 * 7) return `há ${Math.floor(s / 86400)} d`;
  return new Date(d).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
}

function initials(name) {
  const parts = String(name || '?').replace(/^(Profa?\.|Prof\.)\s*/i, '').split(/\s+/).filter(Boolean);
  return ((parts[0]?.[0] || '?') + (parts.length > 1 ? parts[parts.length - 1][0] : '')).toUpperCase();
}

function avatar(id, name, avatarId, size = 40) {
  const st = `width:${size}px;height:${size}px;font-size:${Math.round(size * 0.38)}px;`;
  if (avatarId) return `<span class="avatar" style="${st}"><img src="/api/img/${avatarId}" alt="" loading="lazy"></span>`;
  const h = (Number(id) * 47) % 360;
  return `<span class="avatar" style="${st}background:linear-gradient(135deg,hsl(${h} 70% 55%),hsl(${(h + 50) % 360} 75% 48%))">${esc(initials(name))}</span>`;
}

function roleBadge(role, guest) {
  if (guest) return '<span class="badge banca">Banca</span>';
  if (role === 'professor') return '<span class="badge prof">Professor</span>';
  if (role === 'admin') return '<span class="badge admin">Oficial</span>';
  return '';
}

let toastTimer;
function toast(msg) {
  let el = document.querySelector('.toast');
  if (!el) {
    el = document.createElement('div');
    el.className = 'toast';
    el.setAttribute('role', 'status');
    document.body.appendChild(el);
  }
  el.textContent = msg;
  requestAnimationFrame(() => el.classList.add('show'));
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
}

// Mostra um "parabéns" quando o aluno desbloqueia troféus.
function celebrate(trophies) {
  if (!trophies?.length) return;
  const queue = [...trophies];
  const showNext = () => {
    const t = queue.shift();
    if (!t) return;
    const el = document.createElement('div');
    el.className = 'celebrate';
    el.innerHTML = `<div class="box">
      <div class="emoji">${t.emoji}</div>
      <div class="tiny bold muted" style="text-transform:uppercase;letter-spacing:.1em">Troféu desbloqueado!</div>
      <h2 style="margin:6px 0">${esc(t.name)}</h2>
      <p class="muted" style="margin:0 0 14px">${esc(t.desc)}</p>
      <div class="badge" style="font-size:14px;padding:6px 14px;margin-bottom:18px">+${t.points} pontos</div>
      <button class="btn primary block">Show! 🎉</button></div>`;
    el.addEventListener('click', (e) => {
      if (e.target === el || e.target.closest('button')) {
        el.remove();
        showNext();
      }
    });
    document.body.appendChild(el);
  };
  showNext();
}

function go(path) {
  const target = '#' + path;
  if (location.hash === target) router();
  else location.hash = target;
}

// Diminui a foto no próprio celular antes de enviar (envio rápido, banco leve).
async function resizeImage(file, max = 1080, quality = 0.82) {
  if (!file || !file.type.startsWith('image/')) throw new Error('Escolha um arquivo de imagem.');
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((resolve, reject) => {
      const i = new Image();
      i.onload = () => resolve(i);
      i.onerror = () => reject(new Error('Não consegui abrir essa imagem. Tente outra (JPG ou PNG).'));
      i.src = url;
    });
    const scale = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.naturalWidth * scale);
    canvas.height = Math.round(img.naturalHeight * scale);
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', quality);
  } finally {
    URL.revokeObjectURL(url);
  }
}

// Liga um <form> a uma função assíncrona, travando o botão e mostrando erros.
function onSubmit(form, handler) {
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const btn = form.querySelector('[type=submit]');
    const label = btn?.innerHTML;
    if (btn) { btn.disabled = true; btn.innerHTML = 'Aguarde…'; }
    try {
      await handler(Object.fromEntries(new FormData(form)));
    } catch (err) {
      toast(err.message);
    } finally {
      if (btn && btn.isConnected) { btn.disabled = false; btn.innerHTML = label; }
    }
  });
}

// ---------------------------------------------------------------- ícones
const svg = (d, extra = '') => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}>${d}</svg>`;
const I = {
  home: svg('<path d="M3 10.5 12 3l9 7.5"/><path d="M5 9.5V20a1 1 0 0 0 1 1h4v-6h4v6h4a1 1 0 0 0 1-1V9.5"/>'),
  mural: svg('<path d="M3 11v2a1 1 0 0 0 1 1h2l5 4V6L6 10H4a1 1 0 0 0-1 1z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M18.5 5.5a9 9 0 0 1 0 13"/>'),
  plus: svg('<path d="M12 5v14M5 12h14"/>', 'stroke-width="2.6"'),
  ranking: svg('<path d="M8 21V11H4v10"/><path d="M14 21V4h-4v17"/><path d="M20 21v-7h-4v7"/><path d="M2 21h20"/>'),
  trophy: svg('<path d="M8 21h8M12 17v4"/><path d="M7 4h10v6a5 5 0 0 1-10 0z"/><path d="M17 5h3v2a4 4 0 0 1-4 4M7 5H4v2a4 4 0 0 0 4 4"/>'),
  heart: svg('<path d="M12 20s-7-4.4-9.2-9A5.2 5.2 0 0 1 12 6a5.2 5.2 0 0 1 9.2 5c-2.2 4.6-9.2 9-9.2 9z"/>'),
  comment: svg('<path d="M21 12a8 8 0 0 1-11.6 7.1L4 20.5l1.4-5A8 8 0 1 1 21 12z"/>'),
  back: svg('<path d="M15 18l-6-6 6-6"/>'),
  trash: svg('<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/>'),
  logout: svg('<path d="M15 4h4a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1h-4M10 17l5-5-5-5M15 12H3"/>'),
  send: svg('<path d="M22 2 11 13M22 2l-7 20-4-9-9-4z"/>'),
  medal: svg('<circle cx="12" cy="15" r="6"/><path d="M8.5 10 6 2h4l2 5 2-5h4l-2.5 8"/>'),
};

// ---------------------------------------------------------------- layout
function layout({ title = '', back = false, tab = null, right = '' } = {}, html = '<div class="spinner"></div>') {
  const me = state.me;
  const left = back
    ? `<button class="icon-btn" data-back aria-label="Voltar">${I.back}</button>`
    : '<a href="#/" class="logo" aria-label="Maxx — início">Maxx</a>';
  const meBtn = right || (me ? `<a href="#/perfil/${me.id}" aria-label="Meu perfil">${avatar(me.id, me.name, me.avatar_id, 34)}</a>` : '');
  const plus = isAluno()
    ? `<a href="#/novo" class="plus ${tab === 'novo' ? 'active' : ''}" aria-label="Publicar foto"><span class="plus-btn">${I.plus}</span></a>`
    : `<a href="#/medalha" class="plus ${tab === 'novo' ? 'active' : ''}" aria-label="Dar medalha"><span class="plus-btn">${I.medal}</span></a>`;
  const navItem = (key, href, icon, label) => `<a href="${href}" class="${tab === key ? 'active' : ''}">${icon}<span>${label}</span></a>`;
  root.className = 'app';
  root.innerHTML = `
    <header class="topbar">
      <div style="min-width:40px">${left}</div>
      ${title ? `<div class="title">${esc(title)}</div>` : '<div class="grow"></div>'}
      <div style="min-width:40px;display:flex;justify-content:flex-end">${meBtn}</div>
    </header>
    <main class="view" id="view">${html}</main>
    <nav class="bottomnav" aria-label="Menu principal"><div class="inner">
      ${navItem('feed', '#/', I.home, 'Feed')}
      ${navItem('avisos', '#/avisos', I.mural, 'Avisos')}
      ${plus}
      ${navItem('ranking', '#/ranking', I.ranking, 'Ranking')}
      ${navItem('conquistas', '#/conquistas', I.trophy, 'Conquistas')}
    </div></nav>`;
  return $('#view');
}

function bareLayout(html) {
  root.className = 'app no-nav';
  root.innerHTML = `<main class="view">${html}</main>`;
  return $('.view');
}

// ---------------------------------------------------------------- publicações
function shade(hex) {
  const n = parseInt(hex.slice(1), 16);
  const r = Math.max(0, (n >> 16) - 60), g = Math.max(0, ((n >> 8) & 255) - 60), b = Math.max(0, (n & 255) - 60);
  return `rgb(${r},${g},${b})`;
}

function postCard(p, { detail = false } = {}) {
  const me = state.me;
  const canDelete = p.kind === 'foto' && (p.user_id === me.id || me.role === 'admin');
  const head = `<div class="post-head row">
      <a href="#/perfil/${p.user_id}">${avatar(p.user_id, p.user_name, p.user_avatar, 40)}</a>
      <div class="grow">
        <div class="ellipsis"><a class="name" href="#/perfil/${p.user_id}">${esc(p.user_name)}</a> ${roleBadge(p.user_role, p.user_guest)}</div>
        <div class="tiny muted">${p.user_course ? esc(p.user_course) + ' · ' : ''}${timeAgo(p.created_at)}</div>
      </div>
      ${canDelete ? `<button class="icon-btn" data-del-post="${p.id}" aria-label="Apagar publicação">${I.trash}</button>` : ''}
    </div>`;
  let media = '';
  if (p.kind === 'foto') {
    media = `<div class="post-media" data-dbl="${p.id}">
      <img src="/api/img/${p.image_id}" alt="Foto publicada por ${esc(p.user_name)}" loading="lazy">
      <div class="heart-pop">❤️</div></div>`;
  } else if (p.kind === 'medalha' && p.medal) {
    const m = p.medal;
    media = `<div class="achv" style="background:linear-gradient(135deg, ${m.color}, ${shade(m.color)})">
      <div class="emoji">${m.emoji}</div>
      <div class="kicker">Medalha recebida</div>
      <div class="what">${esc(m.name)}</div>
      ${p.medal_reason ? `<div class="why">“${esc(p.medal_reason)}”</div>` : ''}
      <div class="small" style="position:relative;margin-top:6px;opacity:.9">— ${p.prof_id ? `<a href="#/perfil/${p.prof_id}"><b>${esc(p.prof_name)}</b></a>` : 'professor'}</div>
      <div class="pts">+${m.points} pontos</div></div>`;
  } else if (p.kind === 'trofeu' && p.trophy) {
    const t = p.trophy;
    media = `<div class="achv tier-${t.tier}">
      <div class="emoji">${t.emoji}</div>
      <div class="kicker">Troféu desbloqueado</div>
      <div class="what">${esc(t.name)}</div>
      <div class="why" style="font-style:normal">${esc(t.desc)}</div>
      <div class="pts">+${t.points} pontos</div></div>`;
  }
  const actions = `<div class="post-actions">
      <button data-like="${p.id}" class="${p.liked ? 'liked' : ''}" aria-label="Curtir" aria-pressed="${p.liked}">${I.heart}<span data-likes="${p.id}">${fmt(p.likes)}</span></button>
      <a href="#/post/${p.id}" class="row" style="padding:8px;gap:6px;font-weight:700" aria-label="Comentários">${I.comment}<span>${fmt(p.comments)}</span></a>
    </div>`;
  const caption = p.kind === 'foto' && p.caption
    ? `<div class="caption"><a href="#/perfil/${p.user_id}" class="bold">${esc(p.user_name)}</a> ${esc(p.caption)}</div>`
    : '';
  const more = !detail && p.comments > 0
    ? `<a href="#/post/${p.id}" class="small muted" style="display:block;margin-top:4px">Ver ${p.comments === 1 ? 'o comentário' : `os ${p.comments} comentários`}</a>`
    : '';
  return `<article class="card post" data-post="${p.id}">${head}${media}${actions}<div class="post-body">${caption}${more}</div></article>`;
}

async function likePost(id, { onlyLike = false } = {}) {
  const btns = $$(`[data-like="${id}"]`);
  const wasLiked = btns[0]?.classList.contains('liked');
  if (onlyLike && wasLiked) return;
  const apply = (liked, likes) => {
    btns.forEach((b) => { b.classList.toggle('liked', liked); b.setAttribute('aria-pressed', liked); });
    $$(`[data-likes="${id}"]`).forEach((s) => { s.textContent = fmt(likes); });
  };
  const current = Number(($(`[data-likes="${id}"]`)?.textContent || '0').replace(/\D/g, ''));
  apply(!wasLiked, current + (wasLiked ? -1 : 1));
  try {
    const r = await api(`/api/posts/${id}/like`, { method: 'POST' });
    apply(r.liked, r.likes);
  } catch (err) {
    apply(wasLiked, current);
    toast(err.message);
  }
}

// Cliques em qualquer tela (curtir, apagar, voltar, duplo toque na foto).
let lastTap = { id: null, t: 0 };
root.addEventListener('click', async (e) => {
  const back = e.target.closest('[data-back]');
  if (back) {
    if (history.length > 1) history.back();
    else go('/');
    return;
  }
  const like = e.target.closest('[data-like]');
  if (like) return likePost(like.dataset.like);
  const media = e.target.closest('[data-dbl]');
  if (media) {
    const id = media.dataset.dbl;
    const now = Date.now();
    if (lastTap.id === id && now - lastTap.t < 350) {
      const pop = media.querySelector('.heart-pop');
      pop.classList.remove('go');
      void pop.offsetWidth;
      pop.classList.add('go');
      likePost(id, { onlyLike: true });
      lastTap = { id: null, t: 0 };
    } else {
      lastTap = { id, t: now };
    }
    return;
  }
  const del = e.target.closest('[data-del-post]');
  if (del) {
    if (!confirm('Apagar esta publicação? Os pontos dela também saem do ranking.')) return;
    try {
      await api(`/api/posts/${del.dataset.delPost}`, { method: 'DELETE' });
      toast('Publicação apagada.');
      if (location.hash.startsWith('#/post/')) go('/');
      else del.closest('.post')?.remove();
    } catch (err) {
      toast(err.message);
    }
  }
});

