      const canDel = n.author_id === me.id || me.role === 'admin';
      return `<article class="card notice ${n.pinned ? 'pinned' : ''}">
        <div class="row">
          <a href="#/perfil/${n.author_id}">${avatar(n.author_id, n.author_name, n.author_avatar, 36)}</a>
          <div class="grow"><div class="bold small ellipsis">${esc(n.author_name)} ${roleBadge(n.author_role, n.author_guest)}</div>
          <div class="tiny muted">${timeAgo(n.created_at)}</div></div>
          ${canDel ? `<button class="icon-btn" data-del-notice="${n.id}" aria-label="Apagar aviso">${I.trash}</button>` : ''}
        </div>
        <div class="row" style="gap:6px;margin-top:10px;flex-wrap:wrap">
          ${n.pinned ? '<span class="badge admin">📌 Fixado</span>' : ''}
          <span class="badge">${n.course ? esc(n.course) : 'Todos os cursos'}</span>
          ${official ? '<span class="badge prof">Oficial UniMax</span>' : ''}
        </div>
        <h3>${esc(n.title)}</h3><div class="body">${esc(n.body)}</div></article>`;
    }).join('') : '<div class="empty"><div class="big">📭</div>Nenhum aviso por enquanto.</div>';
    list.addEventListener('click', async (e) => {
      const b = e.target.closest('[data-del-notice]');
      if (!b || !confirm('Apagar este aviso?')) return;
      try {
        await api(`/api/notices/${b.dataset.delNotice}`, { method: 'DELETE' });
        b.closest('.notice').remove();
      } catch (err) { toast(err.message); }
    });
  } catch (err) { $('#list', view).innerHTML = `<div class="empty">${esc(err.message)}</div>`; }
}

// ---------------------------------------------------------------- tela: ranking
async function rankingScreen() {
  const me = state.me;
  const r = state.rank;
  if (r.scope === 'curso' && !r.course) r.course = me.course_id || state.config.courses[0]?.id;
  const view = layout({ title: 'Ranking', tab: 'ranking' }, `
    <div class="segmented" id="scope">
      <button data-v="geral" class="${r.scope === 'geral' ? 'on' : ''}">🌎 Geral</button>
      <button data-v="curso" class="${r.scope === 'curso' ? 'on' : ''}">🎓 Por curso</button>
    </div>
    ${r.scope === 'curso' ? `<div class="chips" style="margin-top:10px" id="courses">${state.config.courses.map((c) => `<button class="chip ${c.id === Number(r.course) ? 'on' : ''}" data-c="${c.id}">${esc(c.short)}</button>`).join('')}</div>` : ''}
    <div class="row" style="justify-content:center;margin-top:10px">
      <div class="segmented" id="period" style="width:240px">
        <button data-v="all" class="${r.period === 'all' ? 'on' : ''}">Sempre</button>
        <button data-v="month" class="${r.period === 'month' ? 'on' : ''}">Este mês</button>
      </div>
    </div>
    <div id="rk"><div class="spinner"></div></div>`);
  $('#scope', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { r.scope = b.dataset.v; rankingScreen(); } });
  $('#period', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { r.period = b.dataset.v; rankingScreen(); } });
  $('#courses', view)?.addEventListener('click', (e) => { const b = e.target.closest('[data-c]'); if (b) { r.course = Number(b.dataset.c); rankingScreen(); } });
  // Rola o curso escolhido para dentro da tela.
  $('#courses .chip.on', view)?.scrollIntoView({ inline: 'center', block: 'nearest' });

  const qs = new URLSearchParams({ period: r.period });
  if (r.scope === 'curso') qs.set('course', r.course);
  try {
    const { ranking } = await api(`/api/ranking?${qs}`);
    const box = $('#rk', view);
    if (!ranking.length) { box.innerHTML = '<div class="empty"><div class="big">🏁</div>Ninguém nesse ranking ainda.</div>'; return; }
    const top = ranking.slice(0, 3);
    const spot = (u, cls, pos) => u ? `<a class="spot ${cls}" href="#/perfil/${u.id}">
        <div style="display:flex;justify-content:center">${avatar(u.id, u.name, u.avatar_id, pos === 1 ? 70 : 56)}</div>
        <div class="nm">${esc(u.name)}</div><div class="pt">${fmt(u.points)} pts</div>
        <div class="block">${pos === 1 ? '🥇' : pos === 2 ? '🥈' : '🥉'}</div></a>` : '<div></div>';
    const rows = ranking.slice(3).map((u, i) => `
      <a class="rank-row ${u.id === me.id ? 'me' : ''}" href="#/perfil/${u.id}">
        <span class="pos">${i + 4}</span>${avatar(u.id, u.name, u.avatar_id, 38)}
        <div class="grow"><div class="bold ellipsis">${esc(u.name)} ${u.is_guest ? roleBadge('aluno', true) : ''}</div><div class="tiny muted">${esc(u.course || '')}</div></div>
        <span class="pts">${fmt(u.points)}</span></a>`).join('');
    const myPos = ranking.findIndex((u) => u.id === me.id);
    box.innerHTML = `
      <div class="podium">${spot(top[1], 'p2', 2)}${spot(top[0], 'p1', 1)}${spot(top[2], 'p3', 3)}</div>
      ${rows ? `<div class="card" style="overflow:hidden">${rows}</div>` : ''}
      ${myPos >= 0 ? `<div class="card pad me-bar row">
        <b style="font-size:20px">#${myPos + 1}</b>
        <div class="grow"><b>Você</b><div class="tiny muted">de ${ranking.length} ${r.scope === 'curso' ? 'no curso' : 'na UniMax'}</div></div>
        <b>${fmt(ranking[myPos].points)} pts</b></div>` : ''}`;
  } catch (err) { $('#rk', view).innerHTML = `<div class="empty">${esc(err.message)}</div>`; }
}

// ---------------------------------------------------------------- tela: conquistas
function trophyCard(t) {
  const pct = Math.round((t.progress / t.target) * 100);
  return `<div class="card trophy ${t.unlocked ? 'done' : 'locked'}">
    ${t.unlocked ? '' : '<span class="lock">🔒</span>'}
    <div class="ic tier-${t.tier}">${t.emoji}</div>
    <h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p>
    <div class="bar"><i style="width:${t.unlocked ? 100 : pct}%"></i></div>
    <div class="meta"><span>${t.unlocked ? `<span class="ok">✓ ${new Date(t.unlocked_at).toLocaleDateString('pt-BR')}</span>` : `${t.progress}/${t.target}`}</span><span>+${t.points} pts</span></div>
  </div>`;
}

async function achievementsScreen([id]) {
  const me = state.me;
  if (!id && isStaff()) return staffAchievements();
  const userId = Number(id || me.id);
  const own = userId === me.id;
  const view = layout({ title: own ? 'Minhas conquistas' : 'Conquistas', back: !own || Boolean(id), tab: 'conquistas' });
  let d;
  try { d = await api(`/api/achievements/${userId}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const got = d.trophies.filter((t) => t.unlocked).length;
  const medalCount = d.medals.length;
  const typesGot = d.medalTypes.filter((m) => m.count).length;
  const canRevoke = (m) => me.role === 'admin' || m.prof_id === me.id;
  const tabs = {
    trofeus: () => {
      const sorted = [...d.trophies].sort((a, b) => (b.unlocked - a.unlocked) || (b.progress / b.target - a.progress / a.target));
      return `<div class="trophy-grid">${sorted.map(trophyCard).join('')}</div>`;
    },
    medalhas: () => `
      <div class="card" style="overflow:hidden">${d.medalTypes.map((m) => `
        <div class="medal-type row ${m.count ? '' : 'locked'}" style="border-bottom:1px solid var(--line)">
          <div class="ic" style="background:${m.color}22">${m.emoji}</div>
          <div class="grow"><b>${esc(m.name)}</b> <span class="tiny muted">+${m.points} pts</span><div class="tiny muted">${esc(m.desc)}</div></div>
          ${m.count ? `<span class="badge" style="background:${m.color};color:#fff;font-size:13px">×${m.count}</span>` : '<span class="tiny muted bold">Falta</span>'}
        </div>`).join('')}</div>
      <div class="section-title">Histórico</div>
      ${d.medals.length ? d.medals.map((m) => `
        <div class="card pad row" style="margin-bottom:8px;align-items:flex-start">
          <div style="font-size:30px">${m.medal?.emoji || '🎖️'}</div>
          <div class="grow"><b>${esc(m.medal?.name || m.type)}</b>
            <div class="small">“${esc(m.reason)}”</div>
            <div class="tiny muted">por ${m.prof_id ? `<a href="#/perfil/${m.prof_id}" class="bold">${esc(m.prof_name)}</a>` : 'professor'} · ${timeAgo(m.created_at)}</div></div>
          ${canRevoke(m) ? `<button class="btn danger sm" data-revoke="${m.id}">Retirar</button>` : ''}
        </div>`).join('') : `<div class="empty"><div class="big">🎖️</div>${own ? 'Você ainda não recebeu medalhas. Elas são dadas pelos professores!' : 'Nenhuma medalha ainda.'}</div>`}`,
    pontos: () => `
      <div class="card pad stack">${d.pointRules.map((r) => `<div class="row"><span style="font-size:24px">${r.emoji}</span><span>${esc(r.text)}</span></div>`).join('')}</div>
      <p class="hint center" style="margin-top:12px">Os pontos somam no ranking geral e no ranking do seu curso. Apagar uma foto tira os pontos dela.</p>`,
  };
  const render = () => {
    view.innerHTML = `
      <div class="card achv-summary">
        <div class="row between">
          <div><div class="small" style="opacity:.85">${own ? 'Seus pontos' : `Pontos de ${esc(d.user.name.split(' ')[0])}`}</div><div class="big">${fmt(d.points)}</div></div>
          <div style="text-align:right" class="small"><b style="font-size:18px">${got}/${d.trophies.length}</b> troféus<br><b style="font-size:18px">${medalCount}</b> medalhas · ${typesGot}/${d.medalTypes.length} tipos</div>
        </div>
        <div class="bar" style="margin-top:12px;background:rgba(255,255,255,.25)"><i style="width:${Math.round((got / d.trophies.length) * 100)}%;background:#fff"></i></div>
      </div>
      <div class="segmented" id="atabs" style="margin:14px 0">
        <button data-v="trofeus" class="${state.achvTab === 'trofeus' ? 'on' : ''}">🏆 Troféus</button>
        <button data-v="medalhas" class="${state.achvTab === 'medalhas' ? 'on' : ''}">🎖️ Medalhas</button>
        <button data-v="pontos" class="${state.achvTab === 'pontos' ? 'on' : ''}">⭐ Pontos</button>
      </div>
      <div id="tabbody">${tabs[state.achvTab]()}</div>`;
    $('#atabs', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { state.achvTab = b.dataset.v; render(); } });
    $('#tabbody', view).addEventListener('click', async (e) => {
      const b = e.target.closest('[data-revoke]');
      if (!b || !confirm('Retirar esta medalha? Os pontos dela saem do ranking.')) return;
      try { await api(`/api/medals/${b.dataset.revoke}`, { method: 'DELETE' }); toast('Medalha retirada.'); achievementsScreen([String(userId)]); } catch (err) { toast(err.message); }
    });
  };
  render();
}

