import puppeteer from 'puppeteer-core';
const base = 'http://localhost:3922';
const out = process.argv[2] || '.';
const browser = await puppeteer.launch({ executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', headless: 'new' });
const errors = [];
async function newPage() {
  const ctx = await browser.createBrowserContext();
  const page = await ctx.newPage();
  await page.setViewport({ width: 390, height: 844, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  return page;
}
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
async function shot(page, name, hash) {
  if (hash) { await page.evaluate((h) => { location.hash = h; }, hash); }
  await wait(1200);
  await page.screenshot({ path: `${out}/${name}.png` });
}

// Aluno da banca
let page = await newPage();
await page.goto(base + '/?banca=banca2026');
await wait(1500);
await page.screenshot({ path: `${out}/01-banca.png` });
await page.type('input[name=name]', 'Profa. Ana (banca)');
await page.click('button[type=submit]');
await wait(1500);
await shot(page, '02-feed');
await page.evaluate(() => window.scrollBy(0, 900));
await shot(page, '03-feed-scroll');
await shot(page, '04-avisos', '#/avisos');
await shot(page, '05-ranking', '#/ranking');
await shot(page, '06-conquistas', '#/conquistas');
await shot(page, '07-novo', '#/novo');
// publica uma foto
const input = await page.$('#file');
await input.uploadFile('C:\\Users\\Guilherme Gimenes\\Documents\\Repos\\tcc\\maxx-leigo-pu\\public\\icons\\icon-512.png');
await wait(800);
await page.type('textarea[name=caption]', 'Testando o Maxx na banca!');
await shot(page, '08-novo-preview');
await page.click('button[type=submit]');
await wait(1500);
await page.screenshot({ path: `${out}/09-celebrate.png` });
await page.click('.celebrate button').catch(() => {});
const me = await page.evaluate(() => fetch('/api/me').then((r) => r.json()));
await shot(page, '10-perfil', `#/perfil/${me.user.id}`);
await shot(page, '11-post', '#/post/1');
await shot(page, '12-perfil-ana', '#/perfil/5');

// Professor da banca
page = await newPage();
await page.goto(base + '/#/login');
await wait(1200);
await page.screenshot({ path: `${out}/13-login.png` });
await page.goto(base + '/?banca=banca2026');
await wait(1200);
await page.type('input[name=name]', 'Prof. Carlos (banca)');
await page.click('[data-role-toggle] button[data-v=professor]');
await page.click('button[type=submit]');
await wait(1500);
await shot(page, '14-medalha', `#/medalha?aluno=${me.user.id}`);
